// Chat Play Pack provides bounded multi-platform rounds and awards through Viewer Foundation.
const MODULE_ID = 'thsv.chat-play-pack'; let operation = Promise.resolve();
const manifest = { contractVersion:'2.0.0-preview.1',moduleId:MODULE_ID,name:'Chat Play Pack',version:'2.5.1',minimumCoreVersion:'2.0.0-preview.1',maximumTestedCoreVersion:'2.0.0-preview.1', minimumBridgeVersion: '2.5.1', maximumTestedBridgeVersion: '2.5.1',dependencies:['thsv.viewer-foundation'],requiredCapabilities:[],configurationSchema:'schemas/config.json',eventSubscriptions:['command.received','stream.offline'],commandsProvided:[{id:'chat-play.play',name:'play'},{id:'chat-play.guess',name:'guess'},{id:'chat-play.answer',name:'answer'},{id:'chat-play.predict',name:'predict'}],actionsProvided:[],browserSourcesProvided:[],dataStorageOwned:['data/addons/thsv.chat-play-pack/','data/addons/.state/thsv.chat-play-pack/'],installationSteps:['Install Viewer Foundation first.','Create matching no-response commands in Command Sync.','Configure original trivia questions before enabling Trivia.'],uninstallationSteps:['Uninstalling preserves only bounded round statistics and pseudonymous Viewer Foundation IDs.'],migrations:[],healthChecks:[{id:'thsv.chat-play-pack.runtime',description:'Confirms bounded rounds, cooldowns, and idempotent Viewer Foundation awards.'}] };
function text(value,max=200){return[...(typeof value==='string'?value.replace(/[\u0000-\u001f\u007f]/gu,' ').replace(/\s+/gu,' ').trim():'')].slice(0,max).join('');}
function settingsFor(context){const raw=context.settings||{};return{enabled:raw.enabled===true,playCommand:text(raw.playCommand,40).toLowerCase()||'play',guessCommand:text(raw.guessCommand,40).toLowerCase()||'guess',answerCommand:text(raw.answerCommand,40).toLowerCase()||'answer',predictCommand:text(raw.predictCommand,40).toLowerCase()||'predict',numberGuessEnabled:raw.numberGuessEnabled!==false,triviaEnabled:raw.triviaEnabled!==false,predictionEnabled:raw.predictionEnabled!==false,awardPoints:Number.isInteger(raw.awardPoints)?Math.min(10000,Math.max(0,raw.awardPoints)):25,roundTimeoutSeconds:Number.isInteger(raw.roundTimeoutSeconds)?Math.min(900,Math.max(15,raw.roundTimeoutSeconds)):120,triviaQuestions:Array.isArray(raw.triviaQuestions)?raw.triviaQuestions.map((line)=>text(line,300)).map((line)=>line.split('|').map((part)=>text(part,180))).filter((parts)=>parts.length===2&&parts.every(Boolean)).slice(0,100):[]};}
function stateFor(raw){const value=raw&&typeof raw==='object'?raw:{};const round=value.round&&typeof value.round==='object'&&['number','trivia','prediction'].includes(value.round.kind)?value.round:null;return{round,roundSequence:Number.isInteger(value.roundSequence)?Math.max(0,value.roundSequence):0,completedRounds:Number.isInteger(value.completedRounds)?Math.max(0,value.completedRounds):0};}
function moderator(event){const roles=new Set((event.user?.roles||[]).map((role)=>text(role,30).toLowerCase()));return roles.has('broadcaster')||roles.has('moderator')||roles.has('mod');}
async function say(context,event,message){return context.chat.send({message:text(message,500),routing:'source',sourcePlatform:event.platform,overflow:'split'});}
async function viewer(context,event){const userId=text(event.user?.id,256);return userId?context.viewerFoundation.getProjection({platform:event.platform,userId}):undefined;}
async function award(context,projection,state,event){const settings=settingsFor(context);if(!projection||settings.awardPoints<1)return;await context.viewerFoundation.mutate({viewerId:projection.viewerId,operation:'add',amount:settings.awardPoints,reason:'Chat Play Pack round winner',idempotencyKey:`${event.eventId}-${state.roundSequence}`.slice(0,128)});}
async function finish(context,event,state,winnerName,projection){await award(context,projection,state,event);state.round=null;state.completedRounds+=1;await context.state.write(state);await context.overlay.publish(`${MODULE_ID}.result.show`,{title:'Chat Play winner',text:winnerName,durationMs:10000});return say(context,event,`${winnerName} wins the round!`);}
async function process(event,context){const settings=settingsFor(context);if(!settings.enabled)return;const state=stateFor(await context.state.read());if(event.eventType==='stream.offline'){state.round=null;await context.state.write(state);return;}if(event.eventType!=='command.received'||event.metadata?.simulated===true||event.user?.actorType!=='human')return;const command=text(event.payload?.command,40).toLowerCase();const args=Array.isArray(event.payload?.arguments)?event.payload.arguments.map((item)=>text(item,180)).filter(Boolean):[];const now=Date.now();if(state.round&&now-state.round.startedAt>settings.roundTimeoutSeconds*1000){state.round=null;await context.state.write(state);}
  if(command===settings.playCommand&&moderator(event)){const kind=(args[0]||'').toLowerCase();if(kind==='stop'){state.round=null;await context.state.write(state);return say(context,event,'Chat Play round stopped.');}if(kind==='number'&&settings.numberGuessEnabled){const maximum=Math.min(1000,Math.max(10,Number(args[1])||100));state.roundSequence+=1;state.round={kind:'number',target:1+Math.floor(Math.random()*maximum),maximum,startedAt:now};await context.state.write(state);return say(context,event,`Guess a number from 1-${maximum} with !${settings.guessCommand}.`);}if(kind==='trivia'&&settings.triviaEnabled&&settings.triviaQuestions.length){const question=settings.triviaQuestions[Math.floor(Math.random()*settings.triviaQuestions.length)];state.roundSequence+=1;state.round={kind:'trivia',question:question[0],answer:question[1].toLowerCase(),startedAt:now};await context.state.write(state);return say(context,event,`${question[0]} Answer with !${settings.answerCommand}.`);}return say(context,event,'Use play number, play trivia, or play stop.');}
  if(command===settings.guessCommand&&state.round?.kind==='number'){const guess=Number(args[0]);if(!Number.isInteger(guess)||guess<1||guess>state.round.maximum)return say(context,event,`Guess 1-${state.round.maximum}.`);if(guess!==state.round.target)return say(context,event,guess<state.round.target?'Higher.':'Lower.');const projection=await viewer(context,event);return finish(context,event,state,text(event.user?.displayName||event.user?.name,80)||'Viewer',projection);}
  if(command===settings.answerCommand&&state.round?.kind==='trivia'){if(text(args.join(' '),180).toLowerCase()!==state.round.answer)return;const projection=await viewer(context,event);return finish(context,event,state,text(event.user?.displayName||event.user?.name,80)||'Viewer',projection);}
  if(command===settings.predictCommand&&settings.predictionEnabled){const action=(args[0]||'').toLowerCase();if(moderator(event)&&action==='open'){const parts=args.slice(1).join(' ').split('|').map((item)=>text(item,120)).filter(Boolean);if(parts.length<3)return say(context,event,'Usage: !predict open Question | Choice 1 | Choice 2');state.roundSequence+=1;state.round={kind:'prediction',question:parts[0],choices:parts.slice(1,7),votes:{},startedAt:now};await context.state.write(state);return say(context,event,`${parts[0]} ${state.round.choices.map((item,index)=>`${index+1}) ${item}`).join(' ')}`);}if(moderator(event)&&action==='resolve'&&state.round?.kind==='prediction'){const choice=Number(args[1])-1;if(!Number.isInteger(choice)||choice<0||choice>=state.round.choices.length)return say(context,event,'Choose a valid winning option number.');const winners=Object.entries(state.round.votes).filter((entry)=>entry[1]===choice).map((entry)=>entry[0]).slice(0,100);for(const viewerId of winners)await context.viewerFoundation.mutate({viewerId,operation:'add',amount:settings.awardPoints,reason:'Chat Play prediction winner',idempotencyKey:`prediction-${state.roundSequence}-${viewerId}`.slice(0,128)});const label=state.round.choices[choice];state.round=null;state.completedRounds+=1;await context.state.write(state);return say(context,event,`${label} wins. ${winners.length} correct prediction(s).`);}if(state.round?.kind==='prediction'){const choice=Number(args[0])-1;if(!Number.isInteger(choice)||choice<0||choice>=state.round.choices.length)return say(context,event,`Vote 1-${state.round.choices.length}.`);const projection=await viewer(context,event);if(!projection)return;state.round.votes[projection.viewerId]=choice;await context.state.write(state);return say(context,event,'Prediction recorded.');}}
}
export default{manifest,required:false,async start(context){operation=Promise.resolve();await context.state.write(stateFor(await context.state.read()));},async stop(){await operation.catch(()=>undefined);operation=Promise.resolve();},async onEvent(event,context){operation=operation.then(()=>process(event,context),()=>process(event,context));await operation;}};
export{stateFor};
